import React, { useState, useEffect } from 'react';
import {
  View, Text, TouchableOpacity, StyleSheet,
  Vibration, Animated, Dimensions, Alert, Image, ScrollView,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import * as SecureStore from 'expo-secure-store';
import * as Haptics from 'expo-haptics';
import * as LocalAuthentication from 'expo-local-authentication';
import { COLORS, ADMIN, SOCIOS, API_URL } from '../constants';
import { useBarberos } from '../hooks/useBarberos';

const { width, height } = Dimensions.get('window');

// Background of the login screen (one definition, used by both gradients below) and the Salón Men SM monogram that sits on it.
// Two PNGs, 132 x 115 dp at 3x (396 x 345 px): gold for a dark background, dark green for a light one. The variant is chosen from the background colour, so it stays right if the background changes.
const FONDO_LOGIN = ['#0f0d07', '#1a1508', '#0a0906'];
const luminosidad = (hex) => { const n = parseInt(hex.slice(1), 16); return (0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255)) / 255; };
const logoVariante = luminosidad(FONDO_LOGIN[0]) < 0.5 ? 'oscuro' : 'claro';
const LOGO_SM = {
  oscuro: 'data:image/png;base64,',
  claro: 'data:image/png;base64,',
};

export default function LoginScreen({ onLogin }) {
  const [step, setStep]       = useState('select');
  const [perfil, setPerfil]   = useState(null);
  const [pin, setPin]         = useState('');
  const [shake]               = useState(new Animated.Value(0));
  const [error, setError]     = useState(false);
  const [bioDisponible, setBioDisponible] = useState(false);
  const [avatarImages, setAvatarImages]   = useState({});
  const { barberos, error: barberosError, retry: barberosRetry } = useBarberos();

  // Animaciones del logo
  const logoScale   = useState(new Animated.Value(0.55))[0];
  const logoOpacity = useState(new Animated.Value(0))[0];
  const logoGlow    = useState(new Animated.Value(1))[0];

  useEffect(() => {
    // Verificar biometría disponible
    LocalAuthentication.hasHardwareAsync().then(has => {
      if (has) LocalAuthentication.isEnrolledAsync().then(setBioDisponible);
    });
  }, []);

  // Animación del logo al montar
  useEffect(() => {
    Animated.parallel([
      Animated.spring(logoScale, {
        toValue: 1, friction: 5, tension: 60, useNativeDriver: true,
      }),
      Animated.timing(logoOpacity, {
        toValue: 1, duration: 500, useNativeDriver: true,
      }),
    ]).start(() => {
      // Pulso sutil continuo tras la entrada
      Animated.loop(
        Animated.sequence([
          Animated.timing(logoGlow, { toValue: 1.04, duration: 1800, useNativeDriver: true }),
          Animated.timing(logoGlow, { toValue: 1,    duration: 1800, useNativeDriver: true }),
        ])
      ).start();
    });

  }, []);

  // Cargar fotos y emojis de cada barbero — separate effect, re-runs
  // whenever the live/cached roster changes (it arrives asynchronously, so
  // it's often still empty on the very first render of the effect above).
  useEffect(() => {
    if (!barberos.length) return;
    let cancelled = false;
    (async () => {
      const imgs = {};
      await Promise.all(barberos.map(async (b) => {
        try {
          const r    = await fetch(`${API_URL}/barbero/${b.bid}/avatar`);
          const json = await r.json();
          if (json.ok && json.imagen) {
            imgs[b.bid] = 'data:' + (json.mime_type || 'image/jpeg') + ';base64,' + json.imagen;
            return;
          }
        } catch {}
        try {
          const em = await SecureStore.getItemAsync(`bp_avatar_${b.bid}`);
          if (em) imgs[b.bid] = em;
        } catch {}
      }));
      if (!cancelled) setAvatarImages(imgs);
    })();
    return () => { cancelled = true; };
  }, [barberos]);

  const seleccionarPerfil = async (p) => {
    setPerfil(p);
    setPin('');
    setError(false);
    // Si es admin y hay biometría disponible, autenticar directamente
    if (p.rol === 'admin' && bioDisponible) {
      autenticarBiometria(p);
    } else {
      setStep('pin');
    }
  };

  const autenticarBiometria = async (p) => {
    try {
      const result = await LocalAuthentication.authenticateAsync({
        promptMessage: 'Verifica tu identidad para acceder como Admin',
        fallbackLabel: 'Usar PIN',
        cancelLabel: 'Cancelar',
        disableDeviceFallback: false,
      });
      if (result.success) {
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
        onLogin({ perfil: p });
      } else if (result.error === 'user_fallback') {
        // Usuario quiere usar PIN
        setStep('pin');
      } else {
        setStep('select');
      }
    } catch {
      setStep('pin'); // fallback a PIN
    }
  };

  const presionarPin = (n) => {
    const maxLen = perfil?.rol === 'admin' ? 6 : 4;
    if (pin.length >= maxLen) return;
    const nuevo = pin + n;
    setPin(nuevo);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    if (nuevo.length === maxLen) validar(nuevo);
  };

  const borrar = () => setPin(p => p.slice(0, -1));

  const rechazar = () => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
    Vibration.vibrate([0, 80, 60, 80]);
    setError(true);
    Animated.sequence([
      Animated.timing(shake, { toValue: 10,  duration: 60, useNativeDriver: true }),
      Animated.timing(shake, { toValue: -10, duration: 60, useNativeDriver: true }),
      Animated.timing(shake, { toValue: 6,   duration: 60, useNativeDriver: true }),
      Animated.timing(shake, { toValue: -6,  duration: 60, useNativeDriver: true }),
      Animated.timing(shake, { toValue: 0,   duration: 60, useNativeDriver: true }),
    ]).start(() => { setPin(''); setError(false); });
  };

  const validar = async (p) => {
    try {
      const res = await fetch(`${API_URL}/api/v2/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenant_id: 'saulfino', bid: perfil.bid, pin: p }),
      });
      const json = await res.json();
      if (res.status === 401 || !json.ok) {
        rechazar();
        return;
      }
      // Store JWT for session persistence
      await SecureStore.setItemAsync('bp_auth_token', json.token);
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      if (!json.pin_set) {
        // First-time setup — pass login PIN so set-pin can verify current_pin
        onLogin({ perfil, requireSetupPin: true, loginPin: p });
      } else {
        onLogin({ perfil });
      }
    } catch {
      // Network unreachable — do NOT fall back to local PINs (security policy)
      setError(true);
      Animated.sequence([
        Animated.timing(shake, { toValue: 6,   duration: 60, useNativeDriver: true }),
        Animated.timing(shake, { toValue: -6,  duration: 60, useNativeDriver: true }),
        Animated.timing(shake, { toValue: 0,   duration: 60, useNativeDriver: true }),
      ]).start(() => { setPin(''); setError(false); });
      Alert.alert('Sin conexión', 'No se pudo conectar al servidor. Intenta de nuevo.');
    }
  };

  // ── GRUPOS DE PERFILES ────────────────────────────────────
  // Barberos group is live/cached (useBarberos()) — never a hardcoded list.
  // Admin/Socios stay static; they aren't hires that change over time.
  const grupos = [
    { titulo: '⚡ Administrador', perfiles: [ADMIN], color: COLORS.gold },
    { titulo: '✂️ Barberos',      perfiles: barberos, color: COLORS.ok, esBarberos: true },
    { titulo: '👁 Socios',        perfiles: SOCIOS,  color: COLORS.blue },
  ];

  // ── PANTALLA SELECCIÓN ────────────────────────────────────
  if (step === 'select') {
    return (
      <LinearGradient colors={FONDO_LOGIN} style={s.container}>
        <Animated.View style={[s.logoWrap, {
          opacity: logoOpacity,
          transform: [{ scale: logoScale }, { scale: logoGlow }],
        }]}>
          <Image source={{ uri: LOGO_SM[logoVariante] }} style={s.logoImg} resizeMode="contain" accessibilityLabel="Salón Men" />
          <Text style={s.brand}>Salón Men</Text>
          <Text style={s.brandSub}>GALERÍA SANTIAGO CENTRO</Text>
        </Animated.View>

        <View style={s.divider} />
        <Text style={s.pregunta}>¿QUIÉN ERES?</Text>

        <ScrollView style={s.grupos} showsVerticalScrollIndicator={false}
          contentContainerStyle={{ paddingBottom: 8 }}>
          {grupos.map(g => (
            <View key={g.titulo}>
              <Text style={[s.grupoLbl, { color: g.color }]}>{g.titulo}</Text>
              {g.esBarberos && g.perfiles.length === 0 ? (
                barberosError ? (
                  <View style={{ paddingHorizontal: 20, paddingVertical: 10 }}>
                    <Text style={{ color: COLORS.text3, fontSize: 13, marginBottom: 8 }}>
                      No se pudo cargar la lista de barberos. Revisa tu conexión.
                    </Text>
                    <TouchableOpacity onPress={barberosRetry} activeOpacity={0.7}
                      style={{ alignSelf: 'flex-start', paddingVertical: 6, paddingHorizontal: 14,
                        borderRadius: 8, borderWidth: 1, borderColor: COLORS.gold }}>
                      <Text style={{ color: COLORS.gold, fontSize: 13, fontWeight: '600' }}>Reintentar</Text>
                    </TouchableOpacity>
                  </View>
                ) : (
                  <Text style={{ color: COLORS.text3, fontSize: 13, paddingHorizontal: 20, paddingVertical: 10 }}>
                    Cargando barberos…
                  </Text>
                )
              ) : g.perfiles.map(p => (
                <TouchableOpacity key={p.bid} style={s.perfilBtn}
                  onPress={() => seleccionarPerfil(p)} activeOpacity={0.7}>
                  <View style={[s.avatar, { backgroundColor: p.bg }]}>
                    {avatarImages[p.bid]?.startsWith('data:')
                      ? <Image source={{ uri: avatarImages[p.bid] }} style={s.avatarImg} />
                      : <Text style={[s.avatarLetra, { color: p.color,
                          fontSize: (avatarImages[p.bid] || p.letra).length > 2 ? 18 : 22 }]}>
                          {avatarImages[p.bid] || p.letra}
                        </Text>
                    }
                  </View>
                  <View style={s.perfilInfo}>
                    <Text style={s.perfilNombre}>{p.nombre}</Text>
                    <Text style={s.perfilRol}>
                      {p.rol === 'admin' ? (bioDisponible ? 'Huella digital' : 'PIN 6 dígitos')
                        : p.rol === 'socio' ? 'Solo visualización'
                        : 'Barbero · PIN 4 dígitos'}
                    </Text>
                  </View>
                  <Text style={[s.arrow, { color: p.color }]}>›</Text>
                </TouchableOpacity>
              ))}
            </View>
          ))}
        </ScrollView>
      </LinearGradient>
    );
  }

  // ── PANTALLA PIN ──────────────────────────────────────────
  const maxLen = perfil?.rol === 'admin' ? 6 : 4;
  const KEYS = ['1','2','3','4','5','6','7','8','9','','0','⌫'];

  return (
    <LinearGradient colors={FONDO_LOGIN} style={s.container}>
      <TouchableOpacity style={s.backBtn} onPress={() => setStep('select')}>
        <Text style={s.backTxt}>← Volver</Text>
      </TouchableOpacity>

      <View style={s.pinHeader}>
        <View style={[s.avatar, { backgroundColor: perfil.bg, width: 72, height: 72, borderRadius: 36, overflow: 'hidden' }]}>
          {avatarImages[perfil.bid]?.startsWith('data:')
            ? <Image source={{ uri: avatarImages[perfil.bid] }} style={{ width: 72, height: 72, borderRadius: 36 }} />
            : <Text style={[s.avatarLetra, { color: perfil.color,
                fontSize: (avatarImages[perfil.bid] || perfil.letra).length > 2 ? 24 : 30 }]}>
                {avatarImages[perfil.bid] || perfil.letra}
              </Text>
          }
        </View>
        <Text style={s.pinNombre}>{perfil.nombre}</Text>
        <Text style={s.pinSub}>
          {perfil.rol === 'admin' ? 'PIN de 6 dígitos' : 'Ingresa tu PIN'}
        </Text>
      </View>

      <Animated.View style={[s.dots, { transform: [{ translateX: shake }] }]}>
        {Array.from({ length: maxLen }).map((_, i) => (
          <View key={i} style={[s.dot, {
            backgroundColor: i < pin.length ? perfil.color : 'transparent',
            borderColor: error ? COLORS.red : i < pin.length ? perfil.color : COLORS.border2,
            width: maxLen === 6 ? 14 : 18,
            height: maxLen === 6 ? 14 : 18,
            borderRadius: maxLen === 6 ? 7 : 9,
          }]} />
        ))}
      </Animated.View>

      {error && <Text style={s.pinError}>PIN incorrecto</Text>}

      {/* Biometría para admin */}
      {perfil?.rol === 'admin' && bioDisponible && (
        <TouchableOpacity style={s.bioBtn} onPress={() => autenticarBiometria(perfil)}>
          <Text style={s.bioBtnTxt}>👆 Usar huella digital</Text>
        </TouchableOpacity>
      )}

      <View style={s.keypad}>
        {KEYS.map((k, i) => {
          if (k === '') return <View key={i} style={s.keyEmpty} />;
          return (
            <TouchableOpacity key={i}
              style={[s.key, k === '⌫' && s.keyDel]}
              onPress={() => k === '⌫' ? borrar() : presionarPin(k)}
              activeOpacity={0.6}>
              <Text style={[s.keyTxt, k === '⌫' && s.keyDelTxt]}>{k}</Text>
            </TouchableOpacity>
          );
        })}
      </View>
    </LinearGradient>
  );
}

const KEY_SIZE = Math.min(width * 0.22, 80);

const s = StyleSheet.create({
  container: { flex: 1, alignItems: 'center', justifyContent: 'space-between',
    paddingTop: height * 0.06, paddingBottom: height * 0.04, paddingHorizontal: 24 },

  logoWrap:  { alignItems: 'center' },
  logoImg:   { width: 132, height: 115, marginBottom: 12 },
  brand:     { fontSize: 28, color: COLORS.text, fontWeight: '300', letterSpacing: 3, marginBottom: 4 },
  brandSub:  { fontSize: 10, color: COLORS.gold, letterSpacing: 2.5, textTransform: 'uppercase' },

  divider:   { width: 40, height: 1, backgroundColor: COLORS.gold3, marginVertical: 16 },
  pregunta:  { fontSize: 12, color: COLORS.text2, letterSpacing: 3.5, textTransform: 'uppercase' },

  grupos:    { width: '100%', flex: 1 },
  grupoLbl:  { fontSize: 10, letterSpacing: 2, textTransform: 'uppercase',
    marginBottom: 6, marginTop: 10, fontWeight: '700' },
  perfilBtn: { flexDirection: 'row', alignItems: 'center', backgroundColor: 'rgba(255,255,255,.06)',
    borderWidth: 1, borderColor: COLORS.border2, borderRadius: 14,
    paddingVertical: 14, paddingHorizontal: 16, gap: 14, marginBottom: 6 },
  avatar:     { width: 48, height: 48, borderRadius: 24,
    alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },
  avatarImg:  { width: 48, height: 48, borderRadius: 24 },
  avatarLetra:{ fontWeight: '700' },
  perfilInfo:{ flex: 1 },
  perfilNombre: { fontSize: 18, color: COLORS.text, fontWeight: '600', letterSpacing: 0.5 },
  perfilRol: { fontSize: 11, color: COLORS.text3, marginTop: 2, textTransform: 'uppercase', letterSpacing: 1 },
  arrow:     { fontSize: 24, fontWeight: '300' },

  backBtn:   { position: 'absolute', top: height * 0.06, left: 24 },
  backTxt:   { fontSize: 16, color: COLORS.text2 },
  pinHeader: { alignItems: 'center', gap: 10, marginTop: height * 0.04 },
  pinNombre: { fontSize: 32, color: COLORS.text, fontWeight: '300', letterSpacing: 2 },
  pinSub:    { fontSize: 13, color: COLORS.text3, letterSpacing: 1.5, textTransform: 'uppercase' },
  dots:      { flexDirection: 'row', gap: 14, marginVertical: 28 },
  dot:       { borderWidth: 2 },
  pinError:  { fontSize: 14, color: COLORS.red, marginBottom: 8 },

  bioBtn:    { backgroundColor: 'rgba(201,168,76,.12)', borderRadius: 20,
    borderWidth: 1, borderColor: 'rgba(201,168,76,.3)',
    paddingHorizontal: 20, paddingVertical: 10, marginBottom: 8 },
  bioBtnTxt: { fontSize: 15, color: COLORS.gold, fontWeight: '600' },

  keypad:    { flexDirection: 'row', flexWrap: 'wrap', width: KEY_SIZE * 3 + 32,
    gap: 10, justifyContent: 'center' },
  key:       { width: KEY_SIZE, height: KEY_SIZE, borderRadius: KEY_SIZE / 2,
    backgroundColor: 'rgba(255,255,255,.09)', borderWidth: 1,
    borderColor: 'rgba(255,255,255,.12)',
    alignItems: 'center', justifyContent: 'center' },
  keyTxt:    { fontSize: 26, color: COLORS.text, fontWeight: '400' },
  keyEmpty:  { width: KEY_SIZE, height: KEY_SIZE },
  keyDel:    { backgroundColor: 'rgba(255,255,255,.04)' },
  keyDelTxt: { fontSize: 20, color: COLORS.text2 },
});
